(typeof window !== "undefined" ? window : globalThis).SignalLab.guides = {"L1-1":{"steps":["先写平移、反转、压缩对关键点的预测，点击保存初始预测。","完成原信号、压缩和组合对照；每组先估计关键读数，再看图填写实测值。平移、反转可推导或自由调参选做。","从 Δ=0.5 s 基线调到 Δ=0.2 s，先估计再填写高度和面积；其他宽度可自由调参选做。","在推导区写关键点映射，在分析区比较预测与测量，说明窄脉冲哪些量变、哪些量不变。"],"evidence":"保存原信号、压缩、组合和 Δ=0.2 s 窄脉冲；写明关键点、峰时、峰值、宽度、高度、面积及单位。"},"L1-2":{"steps":["预测五个系统的线性与时不变性。","为 affine、square 构造非线性反例，为 timescale 构造时变反例。","比较 delay 与 integrator；记录输入、系数、延迟与最大差。","用反例或代数关系解释判定。"],"evidence":"保存参数、两条路径和反例记录。"},"L1-3":{"steps":["先预测三种情况下的曲线起点和长期值。","设初值 y₀=2、输入关闭，保存零输入情况；改为 y₀=0、输入开启，保存零状态情况。","设 y₀=2、输入开启，读 t=0、1、3、5 s 处的全响应和分量，保存本次试验。","改为 y₀=0.5 再比较；在分析区核对每个时刻的分量之和与全响应。"],"evidence":"三种响应的参数记录、四个时刻的分量对照，补一组 y₀=0.5，解释初值与输入各自贡献。"},"L1-4":{"steps":["先预测两个单位矩形的卷积形状与非零范围。","选矩形与矩形，在 t=0.5、1、2.5 观察重叠图、乘积和积分，并逐组保存。","保存三个指定时刻；其他重叠位置可自由调参选做。","切换矩形与系统冲激响应，读取 t=1、2 s 并保存比较，说明积分变量 τ 与观察时刻 t 的区别。"],"evidence":"矩形卷积三个指定时刻、系统输出两个指定读数和 τ、t 的解释。"},"L2-1":{"steps":["保存对平坦区、跳变附近和过冲的预测。","依次选择 K=3、7、15，每次观察合成波与单边幅度谱，保存本次试验。","逐组记录叠加项数、最高频率和跳变附近最大值；需要时关闭各谐波显示以看清合成波。","分析哪些位置更接近方波，以及过冲高度和影响区域是否同步消失。"],"evidence":"三组 K 的记录、项数与最高频率对照、合成图及过冲解释。"},"L2-2":{"steps":["设 A=1、中心 t₀=0，保存 T=0.5、2 s 两种宽度下的频谱预测。","依次设 T=0.5、2 s 保存 X(0) 与第一正零点；T=1 s 用于时移比较。","恢复 T=1，比较中心 0 与 1 s，在 f=0.25 Hz 处读相位并保存。","保持宽度和中心不变，将 A 从 1 改为 2，保存对照并解释幅度变化。"],"evidence":"两种宽度、一时移和一幅度比较；记录零频值、首零点、非零频谱处相位及单位。"},"L2-3":{"steps":["比较一阶 fc=100、500 Hz。","推导两个幅度约束，判断一阶是否可行。","选择最低阶数和截止频率，保存达标设计。","与三阶 fc=200 Hz 比较相移和群延迟。"],"evidence":"保存一阶对照、最低阶设计和高阶比较。"},"L2-4":{"steps":["比较 100、15 Hz 对 10 Hz 余弦的采样。","寻找全部样本吻合的低频候选。","用 4 kHz 采样 3 kHz 输入，比较混叠频率。","接入 L2-3 的采样前滤波器，比较相同增益下的混叠幅度。"],"evidence":"保存低频对照、音频采样和滤波后的结果。"},"L3-1":{"steps":["先预测幅度、衰减率和时移分别进入变换式的哪个位置。","选指数型，A=1，设定 a=1，填受限答案模板并逐组保存。","分别选阶跃和矩形，比较延迟或持续时间，填模板并保存。","独立题：选延迟矩形，设 A=3、开始 t₁=1 s、持续 T=2 s；先在推导区写两个阶跃，再填模板、看反馈并保存。"],"evidence":"指数、矩形脉冲和延迟矩形的模板记录；独立题写出开始、结束、持续时间和完整变换。"},"L3-2":{"steps":["求零初值的 H、X、Y 与部分分式。","测量 y(0)、y(1) 和零状态 t90。","对初值 0.5、2 保留 sY−y₀ 并更新系数。","比较零输入、零状态与全响应。"],"evidence":"保存零状态、t90 和两组非零初值结果。"},"L3-3":{"steps":["比较欠阻尼与过阻尼。","观察右半平面极点对应的发散。","拖动极点或调参，满足超调≤15%、2% 调节时间≤3 s。","用同一设计比较极点、阶跃与频率响应。"],"evidence":"保存欠阻尼、过阻尼、右半平面和设计结果。"},"L3-4":{"steps":["保存对指定 T=0.5、2 s 峰值和峰时的预测。","比较指定的 T=0.5、2 s，保存峰值、峰时和达标状态；其他宽度可自由调参选做。","由两个阶跃之差推导响应及峰值条件，在临界区至少再试两组更细的 T，保存失败与成功记录。","选最短达标方案并保存，在分析区说明参数步长、理论下界，以及为何相邻更短方案不达标。"],"evidence":"两个指定候选、至少两次细调及最终方案；Y(s)、时移响应、峰值不等式与最短性依据。"}};
/* teaching steps end */
